import * as React from 'react';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import type { ThemeOptions } from '@mui/material/styles';
import { inputsCustomizations } from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/shared-theme/customizations/inputs';
import { dataDisplayCustomizations } from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/shared-theme/customizations/dataDisplay';
import { feedbackCustomizations } from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/shared-theme/customizations/feedback';
import { navigationCustomizations } from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/shared-theme/customizations/navigation';
import { surfacesCustomizations } from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/shared-theme/customizations/surfaces';
import { colorSchemes, typography, shadows, shape } from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/shared-theme/themePrimitives';

interface AppThemeProps {
  children: React.ReactNode;
  /**
   * This is for the docs site. You can ignore it or remove it.
   */
  disableCustomTheme?: boolean;
  themeComponents?: ThemeOptions['components'];
}

export default function AppTheme(props: AppThemeProps) {
  const { children, disableCustomTheme, themeComponents } = props;
  const theme = React.useMemo(() => {
    return disableCustomTheme
      ? {}
      : createTheme({
          // For more details about CSS variables configuration, see https://mui.com/material-ui/customization/css-theme-variables/configuration/
          cssVariables: {
            colorSchemeSelector: 'data-mui-color-scheme',
            cssVarPrefix: 'template',
          },
          colorSchemes, // Recently added in v6 for building light & dark mode app, see https://mui.com/material-ui/customization/palette/#color-schemes
          typography,
          shadows,
          shape,
          components: {
            ...inputsCustomizations,
            ...dataDisplayCustomizations,
            ...feedbackCustomizations,
            ...navigationCustomizations,
            ...surfacesCustomizations,
            ...themeComponents,
          },
        });
  }, [disableCustomTheme, themeComponents]);
  if (disableCustomTheme) {
    return <React.Fragment>{children}</React.Fragment>;
  }
  return (
    <ThemeProvider theme={theme} disableTransitionOnChange>
      {children}
    </ThemeProvider>
  );
}

